//! Task 72 — logout and refresh over the wire, when the revocation store
//! cannot record them, and the boot path that restores what it did record.
//!
//! The session-manager suite (`tests/token_revocation_persistence.rs`)
//! proves the `AuthManager` contract across a restart with a stable secret.
//! These tests pin what a CALLER of `/api/auth/logout` and
//! `/api/auth/refresh` is told, and that production boot
//! ([`crate::restore_durable_auth`]) loads the revocations a logout wrote.
//!
//! A real write failure without a fake store: the database file is migrated
//! read-write, then reopened READ-ONLY for the server under test, so every
//! insert into `revoked_tokens` fails inside SQLite itself.

#![cfg(test)]

use crate::auth_middleware::AuthPosture;
use crate::durability_boot_tests::{open_db, temp_db_path, Db};
use crate::handlers::auth::{LOGOUT_NOT_DURABLE_MESSAGE, REFRESH_NOT_DURABLE_MESSAGE};
use crate::router_integration_tests::make_test_state_with_database;
use crate::{build_router, restore_durable_auth, AppState};

use axum::body::{to_bytes, Body};
use axum::http::{Method, Request, StatusCode};
use serde_json::{json, Value};
use session_manager::{DatabaseConfig, DatabaseType, SessionToken, SqliteDatabase};
use std::sync::Arc;
use tower::ServiceExt;

/// A migrated database file reopened read-only: reads work, every write
/// fails.
async fn read_only_db() -> Db {
    let path = temp_db_path();
    drop(open_db(&path).await);
    let cfg = DatabaseConfig {
        db_type: DatabaseType::SQLite,
        url: format!("sqlite://{path}?mode=ro"),
        max_connections: 2,
        connect_timeout: 5,
        run_migrations: false,
    };
    Arc::new(
        SqliteDatabase::new(&cfg)
            .await
            .expect("a migrated sqlite file must open read-only"),
    )
}

/// A state with auth enforced, booted through the production auth restore.
async fn booted_state(db: Db) -> AppState {
    let mut state = make_test_state_with_database(db, None, None).await;
    state.auth_posture = AuthPosture::Required;
    restore_durable_auth(&state)
        .await
        .expect("the production auth restore must succeed over a readable store");
    state
}

async fn dispatch(state: &AppState, request: Request<Body>) -> (StatusCode, Value) {
    let response = build_router(state.clone())
        .oneshot(request)
        .await
        .expect("router must produce a response (oneshot is infallible)");
    let status = response.status();
    let bytes = to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("response body must serialise to finite bytes");
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, body)
}

fn mint(state: &AppState, user_id: &str) -> SessionToken {
    state
        .session_manager
        .auth_manager()
        .create_token(
            user_id,
            None,
            vec!["user".to_string()],
            session_manager::PrincipalKind::Human,
        )
        .expect("test token must mint")
}

/// Over the read-only store, a refresh token that is NOT revoked is stopped
/// only by the store (`PersistenceError`, claim withdrawn, nothing spent); a
/// revoked one would be refused `AccessDenied` from memory first.
async fn assert_unrevoked(state: &AppState, refresh: &str) {
    match state
        .session_manager
        .auth_manager()
        .rotate_refresh_token(refresh)
        .await
    {
        Err(session_manager::SessionError::PersistenceError { .. }) => {}
        other => panic!(
            "the refresh token must still be unrevoked (only the store may stop it), got {:?}",
            other.map(|t| t.id)
        ),
    }
}

fn logout_request(token: &SessionToken) -> Request<Body> {
    Request::builder()
        .method(Method::POST)
        .uri("/api/auth/logout")
        .header("Authorization", format!("Bearer {}", token.token))
        .body(Body::empty())
        .expect("request must build")
}

#[tokio::test]
async fn a_logout_the_store_cannot_record_is_refused_and_the_session_stays_live() {
    let state = booted_state(read_only_db().await).await;
    let token = mint(&state, "user_logout_ro");

    let (status, body) = dispatch(&state, logout_request(&token)).await;
    assert_eq!(
        status,
        StatusCode::SERVICE_UNAVAILABLE,
        "a logout the store refused must not answer 200, got body: {body}"
    );
    assert_eq!(body["success"], json!(false), "body: {body}");
    assert_eq!(body["error"], json!("LOGOUT_NOT_RECORDED"), "body: {body}");
    let message = body["message"].as_str().unwrap_or_default();
    assert_eq!(message, LOGOUT_NOT_DURABLE_MESSAGE);
    assert!(!message.contains("  "), "message: {message:?}");

    // The caller was told the session is still active — it must be.
    let (status, body) = dispatch(
        &state,
        Request::builder()
            .method(Method::GET)
            .uri("/api/auth/keys")
            .header("Authorization", format!("Bearer {}", token.token))
            .body(Body::empty())
            .expect("request must build"),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "after a refused logout the bearer must still authenticate, got body: {body}"
    );
    let refresh = token.refresh_token.clone().expect("refresh token minted");
    assert_unrevoked(&state, &refresh).await;
}

#[tokio::test]
async fn a_refresh_the_store_cannot_record_is_refused_without_calling_the_token_invalid() {
    let state = booted_state(read_only_db().await).await;
    let refresh = mint(&state, "user_refresh_ro")
        .refresh_token
        .expect("refresh token minted");

    let (status, body) = dispatch(
        &state,
        Request::builder()
            .method(Method::POST)
            .uri("/api/auth/refresh")
            .header("Content-Type", "application/json")
            .body(Body::from(json!({ "refresh_token": refresh }).to_string()))
            .expect("request must build"),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::SERVICE_UNAVAILABLE,
        "a refresh the store refused must not be reported as an invalid token, got body: {body}"
    );
    assert_eq!(body["success"], json!(false), "body: {body}");
    let error = body["error"].as_str().unwrap_or_default();
    assert_eq!(error, REFRESH_NOT_DURABLE_MESSAGE);
    assert!(!error.contains("  "), "error: {error:?}");

    assert_unrevoked(&state, &refresh).await;
}

#[tokio::test]
async fn boot_restores_the_revocations_a_logout_recorded() {
    let path = temp_db_path();
    let db = open_db(&path).await;

    let before = booted_state(db.clone()).await;
    let token = mint(&before, "user_logout_rw");
    let (status, body) = dispatch(&before, logout_request(&token)).await;
    assert_eq!(status, StatusCode::OK, "body: {body}");
    assert_eq!(body["success"], json!(true), "body: {body}");

    // Simulated restart: a fresh process state over the SAME database,
    // booted through the production restore.
    let after = make_test_state_with_database(db, None, None).await;
    let restored = restore_durable_auth(&after)
        .await
        .expect("the production auth restore must succeed");
    assert_eq!(
        restored.revocations, 2,
        "the logout's access and refresh revocations must both come back at boot"
    );
}

//! Auth Slice 4 — the WebSocket `SessionCommand` gate.
//!
//! Slice 1 gated four of the five WebSocket command families
//! (`GeometryCommand`, `AICommand`, `TimelineCommand`, `ExportCommand`)
//! behind the in-band `Authenticate` handshake. The fifth —
//! `SessionCommand` (create/join/leave a session, share an object,
//! publish presence) — was left ungated: its match arm carried no
//! `require_ws_auth!` invocation, so any connected socket could create
//! and join sessions, register itself as a collaborator, and publish
//! presence without ever presenting a credential, in the default
//! `AuthPosture::Required` posture too.
//!
//! That is the same #44 silent-lie family Slice 1 exists to close: the
//! surface *reads* as authenticated (four of five arms are gated and the
//! module doc-comment claims the command surface is gated) while one arm
//! silently accepts anonymous mutation. These tests drive a real server
//! over a real socket — the only vantage point from which the
//! connection-path hole is observable — exactly as the Slice 1 WS tests
//! do.

#![cfg(test)]

use crate::auth_middleware::AuthPosture;
use crate::router_integration_tests::make_test_state;
use crate::{build_router, AppState};

use futures::{SinkExt, StreamExt};
use serde_json::{json, Value};
use std::net::SocketAddr;
use tokio_tungstenite::tungstenite::Message as WsMessage;

// =====================================================================
// Harness — mirrors auth_slice1_tests so the two slices assert the same
// wire behaviour with the same fixtures. Kept local because the Slice 1
// helpers are module-private to that file.
// =====================================================================

/// Build a state whose auth posture is explicitly `Required` rather than
/// inherited from the ambient process environment. The default posture
/// is separately pinned in `auth_middleware`'s own tests; here we state
/// the posture we exercise so the test cannot pass merely because the
/// developer's shell lacked a variable.
async fn secure_state() -> AppState {
    let mut state = make_test_state().await;
    state.auth_posture = AuthPosture::Required;
    state
}

/// Serve `state`'s router on an ephemeral loopback port and return the
/// bound address plus the serving task's handle (aborted by the caller
/// to shut the server down).
async fn serve(state: AppState) -> (SocketAddr, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("must bind an ephemeral loopback port");
    let addr = listener
        .local_addr()
        .expect("bound listener has an address");
    let router = build_router(state);
    let handle = tokio::spawn(async move {
        let _ = axum::serve(listener, router).await;
    });
    (addr, handle)
}

/// Connect a WebSocket to `/ws`, send `command_json`, and collect the
/// text frames the server emits until a decisive frame arrives or the
/// deadline passes.
async fn ws_send_and_collect(addr: SocketAddr, command_json: Value) -> Vec<Value> {
    let url = format!("ws://{addr}/ws");
    let (mut socket, _resp) = tokio_tungstenite::connect_async(&url)
        .await
        .expect("WebSocket upgrade must succeed (the /ws upgrade is public)");

    socket
        .send(WsMessage::Text(command_json.to_string().into()))
        .await
        .expect("must send the command frame");

    let frames = collect_ws_frames(&mut socket).await;
    let _ = socket.close(None).await;
    frames
}

/// Drain text frames until a decisive frame (an auth refusal, a session
/// effect, or an authentication failure) arrives or an overall deadline
/// passes. Breaking on a decisive frame keeps the test robust when the
/// whole suite runs in parallel and server tasks are scheduling-starved.
async fn collect_ws_frames<S>(socket: &mut S) -> Vec<Value>
where
    S: futures::Stream<Item = Result<WsMessage, tokio_tungstenite::tungstenite::Error>> + Unpin,
{
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
    let mut frames = Vec::new();
    loop {
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        if remaining.is_zero() {
            break;
        }
        let recv = tokio::time::timeout(
            remaining.min(std::time::Duration::from_millis(2500)),
            socket.next(),
        )
        .await;
        match recv {
            Ok(Some(Ok(WsMessage::Text(t)))) => {
                if let Ok(v) = serde_json::from_str::<Value>(&t) {
                    let decisive = is_auth_refusal_frame(&v)
                        || is_session_effect_frame(&v)
                        || v.get("type").and_then(|t| t.as_str()) == Some("AuthenticationFailed");
                    frames.push(v);
                    if decisive {
                        break;
                    }
                }
            }
            Ok(Some(Ok(_))) => {}                 // ignore non-text
            Ok(Some(Err(_))) | Ok(None) => break, // socket closed
            Err(_) => break,                      // overall/idle deadline
        }
    }
    frames
}

/// A well-formed `ClientMessage::SessionCommand` that creates a session.
///
/// The wire shape is load-bearing for the negative assertion: it must
/// deserialize into the real `SessionCommand`/`CreateSession` arm so
/// that, absent the gate, it actually executes and emits a
/// `ServerMessage::Success` carrying the new `session_id`. A frame that
/// failed to parse would trivially "not execute" and make the test
/// vacuous. `ClientMessage` is `tag="type", content="data"`;
/// `SessionWSCommand` is internally tagged on `cmd`.
fn session_create_frame(request_id: &str, name: &str) -> Value {
    json!({
        "type": "SessionCommand",
        "data": {
            "command": { "cmd": "CreateSession", "name": name, "description": null },
            "request_id": request_id
        }
    })
}

/// True if a frame is a `ServerMessage::Error` whose `error_code` marks
/// an authentication refusal. `ServerMessage` is `tag="type",
/// content="data"`, so `error_code` sits under `data`.
fn is_auth_refusal_frame(f: &Value) -> bool {
    f.get("type").and_then(|t| t.as_str()) == Some("Error")
        && f.get("data")
            .and_then(|d| d.get("error_code"))
            .and_then(|c| c.as_str())
            == Some("auth_required")
}

/// True if a frame looks like an *executed* session command — a
/// `ServerMessage::Success` (CreateSession's acknowledgement, carrying
/// the new session id), a `ServerMessage::SessionUpdate` (join/presence),
/// or the `CollaboratorsUpdate` roster broadcast.
fn is_session_effect_frame(f: &Value) -> bool {
    matches!(
        f.get("type").and_then(|t| t.as_str()),
        Some("Success") | Some("SessionUpdate") | Some("CollaboratorsUpdate")
    )
}

fn has_auth_refusal(frames: &[Value]) -> bool {
    frames.iter().any(is_auth_refusal_frame)
}

fn has_session_effect(frames: &[Value]) -> bool {
    frames.iter().any(is_session_effect_frame)
}

// =====================================================================
// RED — an unauthenticated SessionCommand must be refused, not honoured
// =====================================================================

/// Connect to `/ws` and send a `SessionCommand::CreateSession` without
/// ever authenticating. The server must refuse it with an `auth_required`
/// error and must not create the session.
///
/// **Fails against the pre-Slice-4 tree:** the `SessionCommand` arm
/// carries no `require_ws_auth!`, so the session is created and a
/// `ServerMessage::Success` frame is emitted instead of an
/// `auth_required` error.
#[tokio::test]
async fn unauthenticated_websocket_session_command_is_rejected() {
    let state = secure_state().await;
    let (addr, server) = serve(state).await;

    let frames = ws_send_and_collect(addr, session_create_frame("ws-sess-1", "s4-anon")).await;
    server.abort();

    assert!(
        has_auth_refusal(&frames),
        "an unauthenticated WebSocket SessionCommand must be refused with an \
         `auth_required` error before it touches the session manager. Frames \
         received: {frames:#?}"
    );
    assert!(
        !has_session_effect(&frames),
        "an unauthenticated WebSocket SessionCommand must NOT execute — no \
         session-effect frame (Success / SessionUpdate / CollaboratorsUpdate) \
         may be emitted. Frames received: {frames:#?}"
    );
}

// =====================================================================
// GREEN companions — the gate opens for a valid credential and for the
// dev bypass, so it is a gate and not a blanket refusal.
// =====================================================================

/// Positive path: a client that authenticates in-band with a valid JWT
/// may then drive `SessionCommand`. Proves the gate *opens*.
#[tokio::test]
async fn websocket_session_command_after_authenticate_executes() {
    let state = secure_state().await;

    // Mint a token from the process's single AuthManager — the same one
    // the WS `Authenticate` handler verifies against.
    let token = state
        .session_manager
        .auth_manager()
        .create_token(
            "user_ws_session",
            None,
            vec!["user".to_string()],
            session_manager::PrincipalKind::Human,
        )
        .expect("token minting must succeed")
        .token;

    let (addr, server) = serve(state).await;
    let url = format!("ws://{addr}/ws");
    let (mut socket, _resp) = tokio_tungstenite::connect_async(&url)
        .await
        .expect("WebSocket upgrade must succeed");

    let authenticate = json!({
        "type": "Authenticate",
        "data": { "token": token, "request_id": "ws-auth-s4" }
    });
    socket
        .send(WsMessage::Text(authenticate.to_string().into()))
        .await
        .expect("must send Authenticate");
    socket
        .send(WsMessage::Text(
            session_create_frame("ws-sess-authed", "s4-authed")
                .to_string()
                .into(),
        ))
        .await
        .expect("must send SessionCommand");

    let frames = collect_ws_frames(&mut socket).await;
    let _ = socket.close(None).await;
    server.abort();

    assert!(
        !has_auth_refusal(&frames),
        "an authenticated WebSocket SessionCommand must not be auth-refused. \
         Frames received: {frames:#?}"
    );
    assert!(
        has_session_effect(&frames),
        "after a valid Authenticate frame, the SessionCommand must execute and \
         emit a session-effect frame. Frames received: {frames:#?}"
    );
}

/// Positive control: under the `InsecureDevBypass` posture the same
/// SessionCommand is admitted without a credential — the gate keys on
/// posture (the connection starts authenticated under the bypass) rather
/// than refusing unconditionally, so local development is unaffected.
#[tokio::test]
async fn dev_bypass_admits_websocket_session_command() {
    // make_test_state defaults to InsecureDevBypass.
    let state = make_test_state().await;
    assert_eq!(
        state.auth_posture,
        AuthPosture::InsecureDevBypass,
        "this control must run under the dev-insecure posture"
    );
    let (addr, server) = serve(state).await;

    let frames = ws_send_and_collect(addr, session_create_frame("ws-sess-dev", "s4-dev")).await;
    server.abort();

    assert!(
        !has_auth_refusal(&frames),
        "under InsecureDevBypass a WebSocket SessionCommand must not be \
         auth-refused. Frames received: {frames:#?}"
    );
    assert!(
        has_session_effect(&frames),
        "under InsecureDevBypass the SessionCommand must execute. Frames \
         received: {frames:#?}"
    );
}

//! Auth Slice 5 — API-key lifecycle over HTTP.
//!
//! Closes the #42 residual: before this slice, `AuthManager::provision_api_key`
//! had no production caller, so a running server had NO way to mint, list, or
//! revoke an API key — the only credential the MCP bridge can present
//! (`Authorization: ApiKey …`). These tests pin the whole lifecycle at the wire:
//!
//!   POST   /api/auth/keys        provision (authenticated, self-service)
//!   GET    /api/auth/keys        list own keys (no secret material)
//!   DELETE /api/auth/keys/{id}   revoke own key (durable write-through)
//!
//! Same philosophy as Slice 1: every test drives [`build_router`] end-to-end,
//! because only the assembled router can prove what a caller on the wire
//! actually receives.

#![cfg(test)]

use crate::auth_middleware::AuthPosture;
use crate::router_integration_tests::{make_test_state, make_test_state_with_database};
use crate::{build_router, AppState};

use axum::body::{to_bytes, Body};
use axum::http::{Method, Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

// =====================================================================
// Harness
// =====================================================================

/// A state with auth enforced and the API-key store attached, mirroring
/// production boot (`attach_api_key_store` + rehydrate) so provisioned
/// keys are durable and revocation write-through is exercised for real.
async fn keyed_state() -> AppState {
    let mut state = make_test_state().await;
    state.auth_posture = AuthPosture::Required;
    let auth_manager = state.session_manager.auth_manager();
    auth_manager.attach_api_key_store(state.database.clone());
    auth_manager
        .load_persisted_api_keys()
        .await
        .expect("fresh in-memory store must rehydrate (to zero keys)");
    state
}

/// Dispatch through the fully-assembled router; return status + JSON body.
async fn dispatch(state: &AppState, request: Request<Body>) -> (StatusCode, Value) {
    let response = build_router(state.clone())
        .oneshot(request)
        .await
        .expect("router must produce a response (oneshot is infallible)");
    let status = response.status();
    let bytes = to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("response body must serialise to finite bytes");
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, body)
}

fn request(method: Method, path: &str, auth: Option<&str>, body: Option<Value>) -> Request<Body> {
    let mut builder = Request::builder().method(method).uri(path);
    if let Some(header) = auth {
        builder = builder.header("Authorization", header);
    }
    match body {
        Some(v) => builder
            .header("Content-Type", "application/json")
            .body(Body::from(v.to_string()))
            .expect("request must build"),
        None => builder.body(Body::empty()).expect("request must build"),
    }
}

/// Mint a Bearer credential for `user_id` exactly as the login handler would.
fn bearer_for(state: &AppState, user_id: &str) -> String {
    let token = state
        .session_manager
        .auth_manager()
        .create_token(
            user_id,
            None,
            vec!["user".to_string()],
            session_manager::PrincipalKind::Human,
        )
        .expect("test token must mint");
    format!("Bearer {}", token.token)
}

/// Provision a key over the wire for `user_id`; return (key_id, raw_key).
async fn provision(state: &AppState, user_id: &str, name: &str) -> (String, String) {
    let bearer = bearer_for(state, user_id);
    let (status, body) = dispatch(
        state,
        request(
            Method::POST,
            "/api/auth/keys",
            Some(&bearer),
            Some(json!({ "name": name })),
        ),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "provisioning with a valid Bearer token must succeed, got body: {body}"
    );
    assert_eq!(body["success"], json!(true), "body: {body}");
    let id = body["id"].as_str().expect("key id in response").to_string();
    let raw = body["key"]
        .as_str()
        .expect("raw key must be returned exactly once at provisioning")
        .to_string();
    (id, raw)
}

// =====================================================================
// Provisioning
// =====================================================================

#[tokio::test]
async fn key_provisioning_requires_a_credential() {
    let state = keyed_state().await;
    let (status, _body) = dispatch(
        &state,
        request(
            Method::POST,
            "/api/auth/keys",
            None,
            Some(json!({ "name": "anon-attempt" })),
        ),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::UNAUTHORIZED,
        "an unauthenticated caller must not be able to mint a credential"
    );
}

#[tokio::test]
async fn a_provisioned_key_authenticates_a_request() {
    let state = keyed_state().await;
    let (_id, raw) = provision(&state, "user_alpha", "mcp-server").await;

    assert!(
        raw.starts_with("rosh_"),
        "raw key must carry the configured display prefix, got: {raw}"
    );

    // The freshly minted key must work as a wire credential on a
    // protected route — the exact scheme the MCP bridge sends.
    let (status, body) = dispatch(
        &state,
        request(
            Method::GET,
            "/api/auth/keys",
            Some(&format!("ApiKey {raw}")),
            None,
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "body: {body}");
    assert_eq!(body["success"], json!(true), "body: {body}");
}

#[tokio::test]
async fn permissions_outside_the_user_baseline_are_refused() {
    let state = keyed_state().await;
    let bearer = bearer_for(&state, "user_alpha");
    let (status, body) = dispatch(
        &state,
        request(
            Method::POST,
            "/api/auth/keys",
            Some(&bearer),
            Some(json!({ "name": "escalate", "permissions": ["Admin"] })),
        ),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "a permission string outside the user baseline is refused, not clamped; body: {body}"
    );
    assert_eq!(body["error"], json!("PERMISSIONS_OUTSIDE_BASELINE"));

    // The refusal must be total: no key may have been minted.
    let (status, body) = dispatch(
        &state,
        request(Method::GET, "/api/auth/keys", Some(&bearer), None),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(
        body["keys"].as_array().map(Vec::len),
        Some(0),
        "refused provisioning must not leave a key behind; body: {body}"
    );
}

// =====================================================================
// Listing
// =====================================================================

#[tokio::test]
async fn listing_returns_own_keys_without_any_secret_material() {
    let state = keyed_state().await;
    let (id, raw) = provision(&state, "user_alpha", "mcp-server").await;

    let bearer = bearer_for(&state, "user_alpha");
    let (status, body) = dispatch(
        &state,
        request(Method::GET, "/api/auth/keys", Some(&bearer), None),
    )
    .await;
    assert_eq!(status, StatusCode::OK);

    let keys = body["keys"].as_array().expect("keys array");
    assert_eq!(keys.len(), 1);
    assert_eq!(keys[0]["id"], json!(id));
    assert_eq!(keys[0]["name"], json!("mcp-server"));
    assert_eq!(keys[0]["active"], json!(true));
    assert!(
        keys[0]["prefix"].as_str().is_some(),
        "display prefix is public metadata"
    );

    // Neither the raw secret nor its hash may appear anywhere in the body.
    let serialized = body.to_string();
    assert!(
        !serialized.contains(&raw),
        "raw key must never be listed after provisioning"
    );
    assert!(
        !serialized.contains("key_hash"),
        "the stored hash is secret material and must not be serialised"
    );
}

#[tokio::test]
async fn listing_only_shows_the_callers_own_keys() {
    let state = keyed_state().await;
    let (_a_id, _a_raw) = provision(&state, "user_alpha", "alpha-key").await;
    let (_b_id, _b_raw) = provision(&state, "user_beta", "beta-key").await;

    let bearer_b = bearer_for(&state, "user_beta");
    let (status, body) = dispatch(
        &state,
        request(Method::GET, "/api/auth/keys", Some(&bearer_b), None),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    let keys = body["keys"].as_array().expect("keys array");
    assert_eq!(keys.len(), 1, "user_beta must not see user_alpha's keys");
    assert_eq!(keys[0]["name"], json!("beta-key"));
}

// =====================================================================
// Revocation
// =====================================================================

#[tokio::test]
async fn revoking_a_key_stops_it_authenticating() {
    let state = keyed_state().await;
    let (id, raw) = provision(&state, "user_alpha", "mcp-server").await;
    let api_key_header = format!("ApiKey {raw}");

    // Sanity: works before revocation.
    let (status, _body) = dispatch(
        &state,
        request(Method::GET, "/api/auth/keys", Some(&api_key_header), None),
    )
    .await;
    assert_eq!(status, StatusCode::OK);

    let bearer = bearer_for(&state, "user_alpha");
    let (status, body) = dispatch(
        &state,
        request(
            Method::DELETE,
            &format!("/api/auth/keys/{id}"),
            Some(&bearer),
            None,
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "body: {body}");
    assert_eq!(body["success"], json!(true), "body: {body}");

    let (status, _body) = dispatch(
        &state,
        request(Method::GET, "/api/auth/keys", Some(&api_key_header), None),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::UNAUTHORIZED,
        "a revoked key must be refused on the very next request"
    );
}

#[tokio::test]
async fn a_key_cannot_be_revoked_by_another_user() {
    let state = keyed_state().await;
    let (a_id, a_raw) = provision(&state, "user_alpha", "alpha-key").await;

    let bearer_b = bearer_for(&state, "user_beta");
    let (status, body) = dispatch(
        &state,
        request(
            Method::DELETE,
            &format!("/api/auth/keys/{a_id}"),
            Some(&bearer_b),
            None,
        ),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::NOT_FOUND,
        "another user's key id must read as not-found (no existence leak); body: {body}"
    );

    // Alpha's key must still authenticate.
    let (status, _body) = dispatch(
        &state,
        request(
            Method::GET,
            "/api/auth/keys",
            Some(&format!("ApiKey {a_raw}")),
            None,
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "the key must be untouched");
}

#[tokio::test]
async fn revoking_an_unknown_key_is_a_typed_not_found() {
    let state = keyed_state().await;
    let bearer = bearer_for(&state, "user_alpha");
    let (status, body) = dispatch(
        &state,
        request(
            Method::DELETE,
            "/api/auth/keys/no-such-key-id",
            Some(&bearer),
            None,
        ),
    )
    .await;
    assert_eq!(status, StatusCode::NOT_FOUND);
    assert_eq!(body["error"], json!("KEY_NOT_FOUND"));
}

// =====================================================================
// Durability
// =====================================================================

#[tokio::test]
async fn a_revoked_key_stays_revoked_across_a_restart() {
    let state = keyed_state().await;
    let (id, revoked_raw) = provision(&state, "user_alpha", "to-revoke").await;
    let (_live_id, live_raw) = provision(&state, "user_alpha", "to-keep").await;

    let bearer = bearer_for(&state, "user_alpha");
    let (status, _body) = dispatch(
        &state,
        request(
            Method::DELETE,
            &format!("/api/auth/keys/{id}"),
            Some(&bearer),
            None,
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK);

    // Simulated restart: a fresh process state over the SAME database,
    // rehydrated exactly as production boot does (Slice 3 path).
    let mut restarted = make_test_state_with_database(state.database.clone(), None, None).await;
    restarted.auth_posture = AuthPosture::Required;
    let auth_manager = restarted.session_manager.auth_manager();
    auth_manager.attach_api_key_store(restarted.database.clone());
    let restored = auth_manager
        .load_persisted_api_keys()
        .await
        .expect("persisted keys must rehydrate after restart");
    assert!(
        restored >= 2,
        "both keys must have been persisted (restored {restored})"
    );

    let (status, _body) = dispatch(
        &restarted,
        request(
            Method::GET,
            "/api/auth/keys",
            Some(&format!("ApiKey {live_raw}")),
            None,
        ),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "the live key must survive a restart"
    );

    let (status, _body) = dispatch(
        &restarted,
        request(
            Method::GET,
            "/api/auth/keys",
            Some(&format!("ApiKey {revoked_raw}")),
            None,
        ),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::UNAUTHORIZED,
        "revocation must survive a restart — a revoked key that resurrects on reboot is the Slice-3 defect all over again"
    );
}

