//! Atomic transactions over the kernel surface.
//!
//! An agent composing a part out of multiple primitives needs the
//! "all or nothing" guarantee that comes naturally to a database but
//! has historically been alien to CAD kernels: if step 4 of a 5-step
//! plan fails, the partial state from steps 1–3 must not pollute the
//! main timeline. Without this, an agent's mental model drifts from
//! the kernel's after every error and the user is left with three
//! orphaned solids no one asked for.
//!
//! # Lifecycle
//!
//! ```text
//!   POST /api/tx/begin                 → { "tx_id": "<uuid>" }
//!   POST /api/geometry  (X-Tx-Id: ...) → solid created, tracked under tx
//!   POST /api/geometry  (X-Tx-Id: ...) → solid created, tracked under tx
//!   POST /api/tx/{id}/commit           → solids become permanent (no-op
//!                                        on the kernel; just flips state)
//!   POST /api/tx/{id}/rollback         → every solid created under the
//!                                        transaction is removed
//! ```
//!
//! # Semantics
//!
//! - **Implicit transactions are still allowed.** Mutating endpoints
//!   without an `X-Tx-Id` header behave exactly as before. The
//!   transaction header is opt-in.
//! - **Commit is currently a state flip, not a journal flush.** Solids
//!   are written to the model immediately so other observers see them
//!   live. This matches the WYSIWYG agent expectation and avoids a
//!   second copy of the model. If a strict isolation model is later
//!   needed (one agent's in-flight tx invisible to another agent),
//!   add a per-tx shadow `BRepModel`; the public API does not change.
//! - **Rollback removes the tracked solids from the kernel store.**
//!   The timeline replay log keeps the events for auditability — they
//!   are flagged as `rolled_back` rather than deleted, so an agent can
//!   inspect what was attempted.
//! - **Auto-expire after `TX_TTL`.** A transaction that is neither
//!   committed nor rolled back within the window is rolled back by a
//!   background sweeper. Without a TTL, a crashed agent could leak
//!   solid IDs forever.
//!
//! # Why a separate module
//!
//! Transactions cut across the geometry, timeline, and session layers.
//! Pinning the state machine here (rather than scattered across
//! handlers) keeps the invariants — "track only when Active", "no
//! double-commit", "rollback once" — checkable in one place.

use crate::error_catalog::{ApiError, ErrorCode};
use dashmap::DashMap;
use parking_lot::Mutex;
use serde::Serialize;
use std::{
    sync::Arc,
    time::{Duration, Instant},
};
use uuid::Uuid;

/// HTTP header agents send to associate a request with a transaction.
/// Lowercase per HTTP/2 convention; axum's `HeaderMap` lookup is
/// case-insensitive so client casing does not matter.
pub const TX_ID_HEADER: &str = "x-roshera-tx-id";

/// How long an open transaction may sit idle before the sweeper rolls
/// it back. 1 hour is generous for an interactive agent, tight enough
/// to bound leaks if an agent crashes between begin and commit.
const TX_TTL: Duration = Duration::from_secs(60 * 60);

/// Lifecycle phase. The transition graph is strictly:
/// `Active → Committed` or `Active → RolledBack`. Once terminal, no
/// further mutations are accepted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum TxStatus {
    /// Open and accepting `track_solid` calls.
    Active,
    /// Committed — solids are permanent in the kernel.
    Committed,
    /// Rolled back — solids have been removed from the kernel.
    RolledBack,
    /// Auto-expired and rolled back by the background sweeper.
    Expired,
}

/// Snapshot view of a transaction, safe to serialise to clients.
/// Mirrors the inner `TransactionState` minus the lock.
#[derive(Debug, Clone, Serialize)]
pub struct TransactionView {
    pub tx_id: Uuid,
    pub status: TxStatus,
    pub created_solids: Vec<u32>,
    /// Seconds elapsed since `begin`. Cheap to compute; agents use it
    /// to decide whether to abandon a long-running plan.
    pub age_seconds: u64,
}

/// Inner state guarded by a fast user-space lock. Held only for the
/// duration of `track_solid` / `commit` / `rollback`, so contention
/// is bounded.
#[derive(Debug)]
struct TransactionState {
    id: Uuid,
    status: TxStatus,
    created_at: Instant,
    created_solids: Vec<u32>,
}

/// Concurrent registry of in-flight transactions.
///
/// `DashMap<Uuid, Mutex<TransactionState>>` lets concurrent agents run
/// disjoint transactions without contention; a single transaction is
/// serialised through its inner mutex so two parallel writes from the
/// same agent see consistent state. Cloning the manager itself is
/// cheap (`Arc` everywhere).
#[derive(Debug, Default)]
pub struct TransactionManager {
    transactions: DashMap<Uuid, Arc<Mutex<TransactionState>>>,
}

impl TransactionManager {
    /// Construct an empty manager. Wrapped in `Arc` by `AppState`.
    pub fn new() -> Self {
        Self::default()
    }

    /// Open a fresh transaction. The returned UUID is what callers put
    /// in the `X-Roshera-Tx-Id` header for subsequent mutations.
    pub fn begin(&self) -> Uuid {
        let id = Uuid::new_v4();
        self.transactions.insert(
            id,
            Arc::new(Mutex::new(TransactionState {
                id,
                status: TxStatus::Active,
                created_at: Instant::now(),
                created_solids: Vec::new(),
            })),
        );
        id
    }

    /// Look up a transaction's state for serialisation. Returns `None`
    /// if the ID is unknown (e.g. expired-and-pruned, or the agent
    /// fabricated a UUID).
    pub fn view(&self, tx_id: Uuid) -> Option<TransactionView> {
        let entry = self.transactions.get(&tx_id)?;
        let guard = entry.value().lock();
        Some(TransactionView {
            tx_id: guard.id,
            status: guard.status,
            created_solids: guard.created_solids.clone(),
            age_seconds: guard.created_at.elapsed().as_secs(),
        })
    }

    /// Record a freshly-created solid against the transaction. Called
    /// by mutating handlers when the request carried `X-Roshera-Tx-Id`.
    /// Errors if the transaction is unknown or no longer active — the
    /// handler should treat this as an `ApiError` and not commit the
    /// solid.
    pub fn track_solid(&self, tx_id: Uuid, solid_id: u32) -> Result<(), ApiError> {
        let entry = self
            .transactions
            .get(&tx_id)
            .ok_or_else(|| transaction_not_found(tx_id))?;
        let mut guard = entry.value().lock();
        if guard.status != TxStatus::Active {
            return Err(transaction_not_active(tx_id, guard.status));
        }
        guard.created_solids.push(solid_id);
        Ok(())
    }

    /// Mark a transaction committed. The solids stay in the kernel as
    /// they already are — this is a state-machine flip plus a return
    /// of the IDs the agent successfully claimed. Errors if the
    /// transaction is missing or already terminal.
    pub fn commit(&self, tx_id: Uuid) -> Result<TransactionView, ApiError> {
        let entry = self
            .transactions
            .get(&tx_id)
            .ok_or_else(|| transaction_not_found(tx_id))?;
        let mut guard = entry.value().lock();
        if guard.status != TxStatus::Active {
            return Err(transaction_not_active(tx_id, guard.status));
        }
        guard.status = TxStatus::Committed;
        Ok(TransactionView {
            tx_id: guard.id,
            status: guard.status,
            created_solids: guard.created_solids.clone(),
            age_seconds: guard.created_at.elapsed().as_secs(),
        })
    }

    /// Mark a transaction rolled back and return the list of solids
    /// the caller must remove from the kernel. We do not own the
    /// `BRepModel` here, so the caller (the HTTP handler) performs
    /// the removals against its already-held write lock. This keeps
    /// lock acquisition order consistent across the codebase: model
    /// lock first, transaction lock second.
    ///
    /// Returns the solids that need removal. Errors if the transaction
    /// is missing or already terminal.
    pub fn begin_rollback(&self, tx_id: Uuid) -> Result<Vec<u32>, ApiError> {
        let entry = self
            .transactions
            .get(&tx_id)
            .ok_or_else(|| transaction_not_found(tx_id))?;
        let mut guard = entry.value().lock();
        if guard.status != TxStatus::Active {
            return Err(transaction_not_active(tx_id, guard.status));
        }
        guard.status = TxStatus::RolledBack;
        Ok(guard.created_solids.clone())
    }

    /// Sweeper hook: roll back every transaction past `TX_TTL`.
    /// Returns the IDs to remove from the kernel for each expired
    /// transaction so the caller can clean up under the model lock.
    /// Idempotent: a transaction already terminal is left alone.
    pub fn sweep_expired(&self) -> Vec<(Uuid, Vec<u32>)> {
        let mut to_clean = Vec::new();
        for entry in self.transactions.iter() {
            let mut guard = entry.value().lock();
            if guard.status == TxStatus::Active && guard.created_at.elapsed() > TX_TTL {
                guard.status = TxStatus::Expired;
                to_clean.push((guard.id, guard.created_solids.clone()));
            }
        }
        to_clean
    }

    /// Total live transactions (any status). Exposed for `/health`
    /// introspection and tests.
    pub fn len(&self) -> usize {
        self.transactions.len()
    }

    /// `len() == 0`; required by clippy when `len` is public.
    pub fn is_empty(&self) -> bool {
        self.transactions.is_empty()
    }
}

fn transaction_not_found(tx_id: Uuid) -> ApiError {
    ApiError::new(
        ErrorCode::TransactionNotFound,
        format!("transaction {tx_id} is unknown or has been pruned"),
    )
    .with_hint(
        "Open a fresh transaction with POST /api/tx/begin and use \
         the returned tx_id within the next hour.",
    )
    .with_details(serde_json::json!({ "tx_id": tx_id }))
}

fn transaction_not_active(tx_id: Uuid, status: TxStatus) -> ApiError {
    let status_str = match status {
        TxStatus::Active => "active",
        TxStatus::Committed => "committed",
        TxStatus::RolledBack => "rolled_back",
        TxStatus::Expired => "expired",
    };
    ApiError::new(
        ErrorCode::TransactionNotActive,
        format!("transaction {tx_id} is in terminal state '{status_str}'"),
    )
    .with_details(serde_json::json!({
        "tx_id": tx_id,
        "status": status_str,
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn begin_returns_active_transaction() {
        let m = TransactionManager::new();
        let id = m.begin();
        let view = m.view(id).unwrap();
        assert_eq!(view.status, TxStatus::Active);
        assert!(view.created_solids.is_empty());
    }

    #[test]
    fn track_solid_records_in_order() {
        let m = TransactionManager::new();
        let id = m.begin();
        m.track_solid(id, 7).unwrap();
        m.track_solid(id, 11).unwrap();
        m.track_solid(id, 13).unwrap();
        assert_eq!(m.view(id).unwrap().created_solids, vec![7, 11, 13]);
    }

    #[test]
    fn commit_makes_transaction_terminal() {
        let m = TransactionManager::new();
        let id = m.begin();
        m.track_solid(id, 1).unwrap();
        let view = m.commit(id).unwrap();
        assert_eq!(view.status, TxStatus::Committed);
        assert_eq!(view.created_solids, vec![1]);

        // Second commit must fail loudly — the agent's mental model
        // would silently drift otherwise.
        let err = m.commit(id).unwrap_err();
        assert_eq!(err.code, ErrorCode::TransactionNotActive);

        // Tracking after commit is also rejected.
        let err = m.track_solid(id, 99).unwrap_err();
        assert_eq!(err.code, ErrorCode::TransactionNotActive);
    }

    #[test]
    fn begin_rollback_returns_tracked_solids() {
        let m = TransactionManager::new();
        let id = m.begin();
        m.track_solid(id, 5).unwrap();
        m.track_solid(id, 6).unwrap();
        let solids = m.begin_rollback(id).unwrap();
        assert_eq!(solids, vec![5, 6]);
        assert_eq!(m.view(id).unwrap().status, TxStatus::RolledBack);

        // Cannot roll back twice.
        let err = m.begin_rollback(id).unwrap_err();
        assert_eq!(err.code, ErrorCode::TransactionNotActive);
    }

    #[test]
    fn unknown_tx_id_returns_not_found() {
        let m = TransactionManager::new();
        let err = m.commit(Uuid::new_v4()).unwrap_err();
        assert_eq!(err.code, ErrorCode::TransactionNotFound);
    }

    #[test]
    fn cannot_commit_after_rollback() {
        let m = TransactionManager::new();
        let id = m.begin();
        let _ = m.begin_rollback(id).unwrap();
        let err = m.commit(id).unwrap_err();
        assert_eq!(err.code, ErrorCode::TransactionNotActive);
    }
}

//! Authentication handlers for login, registration, token management,
//! and the API-key lifecycle (Slice 5: provision / list / revoke).

use crate::auth_middleware::AuthInfo;
use crate::AppState;
use axum::{
    extract::{Extension, Path, State},
    http::{header::AUTHORIZATION, HeaderMap, StatusCode},
    response::{Json, Result},
};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use session_manager::{PrincipalKind, SessionError};
use tracing::{error, info, warn};

/// What a logout the store could not record tells its caller (Task 72).
pub(crate) const LOGOUT_NOT_DURABLE_MESSAGE: &str = concat!(
    "The server could not confirm the logout was recorded, ",
    "so the session may still be active. Retry the logout."
);

/// What a refresh the store could not record tells its caller (Task 72).
pub(crate) const REFRESH_NOT_DURABLE_MESSAGE: &str = concat!(
    "The server could not confirm the refresh was recorded, so no new token was issued. ",
    "The refresh token you sent may still be valid; retry with it."
);

/// Response payload for the logout endpoint.
#[derive(Debug, Serialize)]
pub struct LogoutResponse {
    /// Indicates whether the token was successfully revoked.
    pub success: bool,
    /// Human-readable status string.
    pub message: String,
    /// Populated only on the unhappy path; mirrors the codes used by
    /// the other auth handlers in this module.
    pub error: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct LoginRequest {
    pub username: String,
    pub password: String,
    pub remember_me: Option<bool>,
}

#[derive(Debug, Serialize)]
pub struct LoginResponse {
    pub success: bool,
    pub token: Option<String>,
    pub refresh_token: Option<String>,
    pub expires_in: Option<u64>,
    pub user_id: Option<String>,
    pub permissions: Option<Vec<String>>,
    pub error: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct RegisterRequest {
    pub username: String,
    pub email: String,
    pub password: String,
    pub full_name: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct RegisterResponse {
    pub success: bool,
    pub user_id: Option<String>,
    pub message: String,
    pub error: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct RefreshRequest {
    pub refresh_token: String,
}

#[derive(Debug, Serialize)]
pub struct RefreshResponse {
    pub success: bool,
    pub token: Option<String>,
    /// The ROTATED refresh token, `Some` on success.
    ///
    /// Refresh is single-use: the token the client presented is retired by
    /// the exchange, so the replacement has to come back on this field or
    /// the client is left holding a dead credential. Its absence was a
    /// silent hole — the client kept its original refresh token across
    /// every renewal, while the server linked logout-revocation to the
    /// newest one, so from the second hour of any session onwards logging
    /// out left a working refresh token in the client's storage.
    pub refresh_token: Option<String>,
    pub expires_in: Option<u64>,
    pub error: Option<String>,
}

/// Handle user login
///
/// Validates credentials against the user store held by the database persistence layer.
/// The supplied password is verified via Argon2 against the hash stored in `UserData`.
/// A JWT access token and a JWT refresh token are returned on success.
pub async fn login(
    State(state): State<AppState>,
    Json(payload): Json<LoginRequest>,
) -> Result<Json<LoginResponse>> {
    info!("Login attempt for user: {}", payload.username);

    let auth_manager = state.session_manager.auth_manager();

    // Derive the canonical user_id from the username (consistent with registration).
    let user_id = format!("user_{}", payload.username);

    // Load user data from the database — this is the single source of truth.
    let user_data = match state.database.load_user(&user_id).await {
        Ok(u) => u,
        Err(_) => {
            // Use a constant-time-equivalent response to prevent username enumeration.
            warn!("Login failed — user not found: {}", payload.username);
            return Ok(Json(LoginResponse {
                success: false,
                token: None,
                refresh_token: None,
                expires_in: None,
                user_id: None,
                permissions: None,
                error: Some("Invalid credentials".to_string()),
            }));
        }
    };

    if !user_data.is_active {
        warn!("Login rejected — account inactive for user: {}", user_id);
        return Ok(Json(LoginResponse {
            success: false,
            token: None,
            refresh_token: None,
            expires_in: None,
            user_id: None,
            permissions: None,
            error: Some("Account is inactive".to_string()),
        }));
    }

    // Verify the supplied password against the stored Argon2 hash.
    let password_valid = auth_manager
        .verify_password(&payload.password, &user_data.password_hash)
        .unwrap_or(false);

    if !password_valid {
        warn!("Login failed — wrong password for user: {}", user_id);
        return Ok(Json(LoginResponse {
            success: false,
            token: None,
            refresh_token: None,
            expires_in: None,
            user_id: None,
            permissions: None,
            error: Some("Invalid credentials".to_string()),
        }));
    }

    info!("Login successful for user: {}", user_id);

    // Login is a human credential exchange: the caller supplied a
    // username/password pair, which is the human-operator flow. There is
    // no agent-model to honestly attach here.
    let token = auth_manager
        .create_token(
            &user_id,
            Some(user_data.email.clone()),
            vec!["user".to_string()],
            PrincipalKind::Human,
        )
        .map_err(|e| {
            error!("Failed to create token: {:?}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, "Token creation failed")
        })?;

    // The refresh token is embedded inside the SessionToken returned by create_token.
    let refresh_token = token.refresh_token.clone().unwrap_or_default();
    let permissions = get_user_permission_strings();

    Ok(Json(LoginResponse {
        success: true,
        token: Some(token.token),
        refresh_token: Some(refresh_token),
        expires_in: Some(token.expires_at.timestamp() as u64),
        user_id: Some(user_id),
        permissions: Some(permissions),
        error: None,
    }))
}

/// Handle user registration
///
/// Validates the supplied username, email, and password, hashes the password with
/// Argon2, and persists a new `UserData` record through the database persistence layer.
/// The canonical `user_id` is derived as `"user_{username}"` for consistent lookups
/// in the login handler.
pub async fn register(
    State(state): State<AppState>,
    Json(payload): Json<RegisterRequest>,
) -> Result<Json<RegisterResponse>> {
    info!("Registration attempt for user: {}", payload.username);

    let auth_manager = state.session_manager.auth_manager();

    if payload.username.len() < 3 {
        return Ok(Json(RegisterResponse {
            success: false,
            user_id: None,
            message: "Username must be at least 3 characters".to_string(),
            error: Some("INVALID_USERNAME".to_string()),
        }));
    }

    if !payload
        .username
        .chars()
        .all(|c| c.is_alphanumeric() || c == '_' || c == '-')
    {
        return Ok(Json(RegisterResponse {
            success: false,
            user_id: None,
            message: "Username may only contain letters, digits, hyphens, and underscores"
                .to_string(),
            error: Some("INVALID_USERNAME_CHARS".to_string()),
        }));
    }

    // Derive the canonical user_id to ensure consistent lookup in login.
    let user_id = format!("user_{}", payload.username);

    // Reject if this username is already registered.
    if state.database.load_user(&user_id).await.is_ok() {
        warn!(
            "Registration rejected — username already taken: {}",
            payload.username
        );
        return Ok(Json(RegisterResponse {
            success: false,
            user_id: None,
            message: "Username is already taken".to_string(),
            error: Some("USERNAME_TAKEN".to_string()),
        }));
    }

    // Validate and hash the password using Argon2 via AuthManager.
    // hash_password also enforces the configured password complexity requirements.
    let password_hash = match auth_manager.hash_password(&payload.password) {
        Ok(hash) => hash,
        Err(e) => {
            warn!(
                "Password validation failed for user {}: {:?}",
                payload.username, e
            );
            return Ok(Json(RegisterResponse {
                success: false,
                user_id: None,
                message: "Password does not meet security requirements".to_string(),
                error: Some(format!("{:?}", e)),
            }));
        }
    };

    let now = Utc::now();
    let user_data = session_manager::UserData {
        id: user_id.clone(),
        email: payload.email.clone(),
        name: payload
            .full_name
            .clone()
            .unwrap_or_else(|| payload.username.clone()),
        password_hash,
        created_at: now,
        last_login: None,
        is_active: true,
        is_verified: false, // Email verification is a separate flow.
        profile: serde_json::Value::Object(serde_json::Map::new()),
    };

    if let Err(e) = state.database.save_user(&user_data).await {
        error!(
            "Failed to persist user {} during registration: {:?}",
            user_id, e
        );
        return Ok(Json(RegisterResponse {
            success: false,
            user_id: None,
            message: "Registration failed due to a server error".to_string(),
            error: Some("STORAGE_ERROR".to_string()),
        }));
    }

    info!(
        "Registration successful: user '{}' (id: {})",
        payload.username, user_id
    );

    Ok(Json(RegisterResponse {
        success: true,
        user_id: Some(user_id),
        message: format!(
            "User '{}' registered successfully. Please login with your credentials.",
            payload.username
        ),
        error: None,
    }))
}

#[derive(Debug, Deserialize)]
pub struct ChangePasswordRequest {
    pub current_password: String,
    pub new_password: String,
}

#[derive(Debug, Serialize)]
pub struct ChangePasswordResponse {
    pub success: bool,
    pub message: String,
    /// Populated only on the unhappy path; mirrors the codes used by the
    /// other auth handlers in this module.
    pub error: Option<String>,
}

/// `POST /api/auth/password` — change the caller's own password.
///
/// Until this existed there was no way for anyone to change a password by
/// any route: the auth surface was login / register / refresh / logout, so
/// the only remedies were a direct database write or re-registering under a
/// new name. A credential you cannot rotate is a credential you cannot
/// contain once it leaks.
///
/// The current password is required even though the caller already holds a
/// valid token. A bearer token proves *possession*, and possession is
/// exactly what is in doubt when a credential change matters — an
/// unattended session or a leaked token would otherwise be enough to lock
/// the owner out of their own account. Re-proving knowledge is what makes
/// this a change rather than a takeover, so it is checked, not assumed.
///
/// The new password goes through `AuthManager::hash_password`, which
/// applies the configured complexity policy before hashing. A rejection
/// there is returned verbatim as a typed refusal rather than being softened
/// or bypassed: the policy is the operator's decision (`ROSHERA_PASSWORD_*`),
/// not this handler's to negotiate.
///
/// ⚠ Known limitation, stated rather than hidden: tokens already issued
/// stay valid until they expire. `AuthManager` revokes individual tokens
/// (that is what logout does) but has no per-user bulk revocation, so this
/// rotates the secret without ending live sessions. Anyone treating a
/// password change as "kick every other session out" would be wrong today.
pub async fn change_password(
    State(state): State<AppState>,
    Extension(auth_info): Extension<AuthInfo>,
    Json(payload): Json<ChangePasswordRequest>,
) -> (StatusCode, Json<ChangePasswordResponse>) {
    let auth_manager = state.session_manager.auth_manager();
    let user_id = auth_info.user_id.clone();

    let mut user_data = match state.database.load_user(&user_id).await {
        Ok(u) => u,
        Err(e) => {
            // The token authenticated, so the account should exist. If it
            // does not, that is a server-side inconsistency, not a client
            // error — say so instead of reporting bad credentials.
            error!("Password change: authenticated user {user_id} not loadable: {e:?}");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(ChangePasswordResponse {
                    success: false,
                    message: "Could not load the account for this token".to_string(),
                    error: Some("USER_NOT_LOADABLE".to_string()),
                }),
            );
        }
    };

    if !user_data.is_active {
        warn!("Password change rejected — account inactive: {user_id}");
        return (
            StatusCode::FORBIDDEN,
            Json(ChangePasswordResponse {
                success: false,
                message: "Account is inactive".to_string(),
                error: Some("ACCOUNT_INACTIVE".to_string()),
            }),
        );
    }

    let current_valid = auth_manager
        .verify_password(&payload.current_password, &user_data.password_hash)
        .unwrap_or(false);

    if !current_valid {
        warn!("Password change rejected — wrong current password: {user_id}");
        return (
            StatusCode::UNAUTHORIZED,
            Json(ChangePasswordResponse {
                success: false,
                message: "Current password is incorrect".to_string(),
                error: Some("INVALID_CREDENTIALS".to_string()),
            }),
        );
    }

    // Rotating to the same secret is not a rotation. Refusing is honest:
    // reporting success would tell the caller their credential changed when
    // nothing about it did.
    if payload.new_password == payload.current_password {
        return (
            StatusCode::BAD_REQUEST,
            Json(ChangePasswordResponse {
                success: false,
                message: "The new password is the same as the current one".to_string(),
                error: Some("PASSWORD_UNCHANGED".to_string()),
            }),
        );
    }

    let new_hash = match auth_manager.hash_password(&payload.new_password) {
        Ok(hash) => hash,
        Err(e) => {
            // Forward the policy's own reason — "must contain uppercase
            // letter" is actionable, "invalid password" is not.
            let reason = match &e {
                SessionError::InvalidInput { field } => field.clone(),
                other => format!("{other:?}"),
            };
            warn!("Password change rejected by policy for {user_id}: {reason}");
            return (
                StatusCode::BAD_REQUEST,
                Json(ChangePasswordResponse {
                    success: false,
                    message: reason,
                    error: Some("PASSWORD_POLICY".to_string()),
                }),
            );
        }
    };

    user_data.password_hash = new_hash;

    if let Err(e) = state.database.update_user(&user_data).await {
        error!("Password change failed to persist for {user_id}: {e:?}");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(ChangePasswordResponse {
                success: false,
                message: "Password change failed due to a server error".to_string(),
                error: Some("STORAGE_ERROR".to_string()),
            }),
        );
    }

    info!("Password changed for user: {user_id}");

    (
        StatusCode::OK,
        Json(ChangePasswordResponse {
            success: true,
            message: "Password changed. Existing tokens remain valid until they expire."
                .to_string(),
            error: None,
        }),
    )
}

/// Handle token refresh
///
/// The supplied refresh token must be a valid, unexpired JWT signed by this server.
/// The `sub` claim in the refresh token is used to identify the user for whom
/// a new access token is issued. The refresh token itself is validated and
/// spent by `AuthManager::rotate_refresh_token` — signature, audience
/// (`aud == ["refresh"]` exactly), expiry, then an atomic single-use claim —
/// so revoked, spent or expired refresh tokens are rejected, and so is an
/// ACCESS token presented here, which `verify_token` would have accepted,
/// letting a stolen one-hour credential be rolled forward indefinitely.
/// Rotation is the only path that accepts a refresh token.
pub async fn refresh_token(
    State(state): State<AppState>,
    Json(payload): Json<RefreshRequest>,
) -> Result<Json<RefreshResponse>> {
    info!("Token refresh attempt");

    let auth_manager = state.session_manager.auth_manager();

    // Rotate: verify the presented refresh token (signature, audience
    // `aud == ["refresh"]` exactly, revocation, expiry), mint a fresh
    // access + refresh pair, and retire the presented one. A bare UUID, a
    // tampered token, an access token, or an already-spent refresh token
    // is rejected here.
    let rotated = match auth_manager
        .rotate_refresh_token(&payload.refresh_token)
        .await
    {
        Ok(t) => t,
        // The store could not record the spend. The presented token was NOT
        // spent and is still good; "invalid or expired" would tell the
        // client to throw away a working credential.
        Err(SessionError::PersistenceError { reason }) => {
            error!("Token refresh NOT performed — spend not recorded: {reason}");
            return Err((
                StatusCode::SERVICE_UNAVAILABLE,
                Json(RefreshResponse {
                    success: false,
                    token: None,
                    refresh_token: None,
                    expires_in: None,
                    error: Some(REFRESH_NOT_DURABLE_MESSAGE.to_string()),
                }),
            )
                .into());
        }
        Err(e) => {
            warn!("Token refresh rejected — invalid token: {:?}", e);
            return Ok(Json(RefreshResponse {
                success: false,
                token: None,
                refresh_token: None,
                expires_in: None,
                error: Some("Invalid or expired refresh token".to_string()),
            }));
        }
    };

    // The rotated refresh token MUST be returned. It is not a convenience:
    // the client stores what it is given, and a client left holding the
    // retired token cannot renew, while a client left holding a token the
    // server never linked to its access token cannot be logged out.
    let refresh_token = match rotated.refresh_token.clone() {
        Some(rt) => rt,
        None => {
            // `create_token` always mints one; a None here means that
            // invariant broke. Refuse rather than hand back a half-rotated
            // session whose refresh token is now unrecoverable.
            error!(
                "Token refresh produced no refresh token for user: {}",
                rotated.user_id
            );
            // `.into()` because this handler's `Result` carries axum's
            // `ErrorResponse`; the `?` operator elsewhere in this file does
            // that conversion implicitly, an explicit `return Err` does not.
            return Err((StatusCode::INTERNAL_SERVER_ERROR, "Token creation failed").into());
        }
    };

    info!("Token refresh successful for user: {}", rotated.user_id);

    Ok(Json(RefreshResponse {
        success: true,
        token: Some(rotated.token),
        refresh_token: Some(refresh_token),
        expires_in: Some(rotated.expires_at.timestamp() as u64),
        error: None,
    }))
}

/// Handle user logout
///
/// Extracts the bearer token from the `Authorization` header, verifies it via
/// `AuthManager::verify_token` (which rejects tampered, expired, or already
/// revoked tokens), then revokes its `jti` so subsequent requests using the
/// same token fail authentication.
///
/// Idempotent: revoking an already-revoked token surfaces as a verification
/// failure and returns success: false with an explanatory error code, but
/// otherwise has no side effects.
pub async fn logout(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<LogoutResponse>> {
    let auth_manager = state.session_manager.auth_manager();

    // Extract the Bearer token from the Authorization header.
    let raw_token = match headers
        .get(AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .and_then(|s| s.strip_prefix("Bearer "))
        .map(|s| s.trim().to_string())
    {
        Some(t) if !t.is_empty() => t,
        _ => {
            warn!("Logout rejected — missing or malformed Authorization header");
            return Ok(Json(LogoutResponse {
                success: false,
                message: "Missing bearer token".to_string(),
                error: Some("MISSING_TOKEN".to_string()),
            }));
        }
    };

    // Verify the token to surface its jti. A revoked or expired token will
    // fail verification — we treat that as a no-op success from the caller's
    // perspective (logout is idempotent) but log the rejection for audit.
    let claims = match auth_manager.verify_token(&raw_token) {
        Ok(c) => c,
        Err(e) => {
            warn!("Logout: token already invalid or revoked: {:?}", e);
            return Ok(Json(LogoutResponse {
                success: false,
                message: "Token already invalid".to_string(),
                error: Some("INVALID_TOKEN".to_string()),
            }));
        }
    };

    // Durable before done: `revoke_token` records both revocations in the
    // store before it changes anything in memory. If the store refused, the
    // session is still fully active, and saying "logged out" would be a lie
    // that a restart would expose — so the caller hears that it did not
    // happen, with a code distinct from "your token was already invalid".
    if let Err(e) = auth_manager
        .revoke_token(&claims.jti, "user_logout", &claims.sub)
        .await
    {
        error!(
            "Logout NOT recorded for user {} (token {}): {}",
            claims.sub, claims.jti, e
        );
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(LogoutResponse {
                success: false,
                message: LOGOUT_NOT_DURABLE_MESSAGE.to_string(),
                error: Some("LOGOUT_NOT_RECORDED".to_string()),
            }),
        )
            .into());
    }
    info!(
        "Logout successful — token {} revoked for user {}",
        claims.jti, claims.sub
    );

    Ok(Json(LogoutResponse {
        success: true,
        message: "Logged out successfully".to_string(),
        error: None,
    }))
}

/// Default permission strings returned on successful login.
///
/// These reflect the baseline "user" role. Fine-grained per-session permissions
/// are enforced by the `PermissionManager` when the user joins a session and are
/// stored in `UserPermissions` records, not in the JWT itself.
fn get_user_permission_strings() -> Vec<String> {
    vec![
        "ViewGeometry".to_string(),
        "CreateGeometry".to_string(),
        "ModifyGeometry".to_string(),
        "ExportGeometry".to_string(),
    ]
}

// =====================================================================
// API-key lifecycle (Slice 5)
// =====================================================================

#[derive(Debug, Deserialize)]
pub struct ProvisionKeyRequest {
    pub name: String,
    /// Requested permission strings. Omitted ⇒ the user baseline. Any
    /// string outside the baseline is refused (never silently clamped).
    pub permissions: Option<Vec<String>>,
    pub expires_in_days: Option<i64>,
    /// What kind of principal this key will belong to (AUTHORSHIP-A2).
    ///
    /// This is a *declaration by the provisioner*, and that is the whole
    /// point: it is the only attestation that exists. Omitted ⇒
    /// [`PrincipalKind::Unspecified`], which maps to `Author::User` — the
    /// minimal-commitment authorship, carrying only the verified id.
    ///
    /// Declaring `Agent { model }` is what lets an agent's operations be
    /// recorded as `Author::AIAgent` at all. Note the residual: a human
    /// may declare an agent key and have their own manual actions
    /// recorded as an agent's. That is a *recorded, explicit* claim by an
    /// authenticated caller about a credential they own, which is a
    /// strictly smaller problem than silently inferring the value — and
    /// it is the same open residual tracked for timeline authorship.
    #[serde(default)]
    pub principal: Option<PrincipalKind>,
}

#[derive(Debug, Serialize)]
pub struct ProvisionKeyResponse {
    pub success: bool,
    pub id: Option<String>,
    /// The raw secret — returned exactly once, at provisioning. Only its
    /// SHA-256 hash is stored; it can never be retrieved again.
    pub key: Option<String>,
    pub prefix: Option<String>,
    pub name: Option<String>,
    pub expires_at: Option<DateTime<Utc>>,
    pub message: String,
    pub error: Option<String>,
}

/// The public projection of an API key. Deliberately a separate struct
/// from `session_manager::ApiKey` so `key_hash` can never leak through a
/// serializer change.
#[derive(Debug, Serialize)]
pub struct ApiKeySummary {
    pub id: String,
    pub name: String,
    pub prefix: String,
    pub created_at: DateTime<Utc>,
    pub last_used: Option<DateTime<Utc>>,
    pub expires_at: Option<DateTime<Utc>>,
    pub active: bool,
}

#[derive(Debug, Serialize)]
pub struct ListKeysResponse {
    pub success: bool,
    pub keys: Vec<ApiKeySummary>,
    pub error: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct RevokeKeyResponse {
    pub success: bool,
    pub message: String,
    pub error: Option<String>,
}

/// `POST /api/auth/keys` — provision an API key for the authenticated
/// caller (self-service; the key is always minted for `auth_info.user_id`).
///
/// The raw key appears in this response and nowhere else, ever. Requested
/// permissions must be a subset of the user baseline — anything broader is
/// a typed refusal, because a caller must not be able to mint a credential
/// stronger than the one they authenticated with.
pub async fn provision_api_key_handler(
    State(state): State<AppState>,
    Extension(auth_info): Extension<AuthInfo>,
    Json(payload): Json<ProvisionKeyRequest>,
) -> (StatusCode, Json<ProvisionKeyResponse>) {
    let name = payload.name.trim();
    if name.is_empty() || name.len() > 64 {
        return (
            StatusCode::BAD_REQUEST,
            Json(ProvisionKeyResponse {
                success: false,
                id: None,
                key: None,
                prefix: None,
                name: None,
                expires_at: None,
                message: "Key name must be 1–64 characters".to_string(),
                error: Some("INVALID_KEY_NAME".to_string()),
            }),
        );
    }

    let baseline = get_user_permission_strings();
    let permissions = payload.permissions.unwrap_or_else(|| baseline.clone());
    if let Some(outside) = permissions.iter().find(|p| !baseline.contains(p)) {
        warn!(
            "API-key provisioning refused for {} — permission outside baseline: {}",
            auth_info.user_id, outside
        );
        return (
            StatusCode::BAD_REQUEST,
            Json(ProvisionKeyResponse {
                success: false,
                id: None,
                key: None,
                prefix: None,
                name: None,
                expires_at: None,
                message: format!(
                    "Permission '{outside}' is outside the user baseline and cannot be granted to a key"
                ),
                error: Some("PERMISSIONS_OUTSIDE_BASELINE".to_string()),
            }),
        );
    }

    let auth_manager = state.session_manager.auth_manager();
    // AUTHORSHIP-A2: the new key's principal is DECLARED by the request,
    // defaulting to `Unspecified` — it is deliberately NOT inherited from
    // the requesting credential (`auth_info.principal`).
    //
    // Inheritance looks conservative and is in fact a fabrication in both
    // directions. A human operator provisioning a key *for their agent*
    // would stamp it `Human`, so every operation that agent later performs
    // records as `Author::User` — agent work laundered as human work in an
    // append-only log, which is exactly the impersonation class
    // AUTHORSHIP-A1 closed. And an agent provisioning a key would stamp it
    // `Agent { model: <its own model> }` even though the key may be minted
    // for a different agent running a different model.
    //
    // Who provisions a credential simply does not determine whose
    // credential it is. Unknown-until-declared is the only honest default.
    let principal = payload.principal.clone().unwrap_or_default();
    match auth_manager
        .provision_api_key(
            &auth_info.user_id,
            name,
            permissions,
            payload.expires_in_days,
            principal,
        )
        .await
    {
        Ok((raw_key, api_key)) => {
            info!(
                "API key '{}' ({}) provisioned for user {}",
                api_key.name, api_key.id, auth_info.user_id
            );
            (
                StatusCode::OK,
                Json(ProvisionKeyResponse {
                    success: true,
                    id: Some(api_key.id),
                    key: Some(raw_key),
                    prefix: Some(api_key.prefix),
                    name: Some(api_key.name),
                    expires_at: api_key.expires_at,
                    message: "Store this key now — it cannot be retrieved again".to_string(),
                    error: None,
                }),
            )
        }
        Err(e) => {
            error!(
                "API-key provisioning failed for user {}: {:?}",
                auth_info.user_id, e
            );
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(ProvisionKeyResponse {
                    success: false,
                    id: None,
                    key: None,
                    prefix: None,
                    name: None,
                    expires_at: None,
                    message: "Key could not be provisioned durably".to_string(),
                    error: Some("PROVISION_FAILED".to_string()),
                }),
            )
        }
    }
}

/// `GET /api/auth/keys` — list the caller's own keys. No secret material:
/// the response carries the display prefix and metadata only.
pub async fn list_api_keys_handler(
    State(state): State<AppState>,
    Extension(auth_info): Extension<AuthInfo>,
) -> (StatusCode, Json<ListKeysResponse>) {
    let keys = state
        .session_manager
        .auth_manager()
        .list_api_keys(&auth_info.user_id)
        .into_iter()
        .map(|k| ApiKeySummary {
            id: k.id,
            name: k.name,
            prefix: k.prefix,
            created_at: k.created_at,
            last_used: k.last_used,
            expires_at: k.expires_at,
            active: k.active,
        })
        .collect();
    (
        StatusCode::OK,
        Json(ListKeysResponse {
            success: true,
            keys,
            error: None,
        }),
    )
}

/// `DELETE /api/auth/keys/{id}` — revoke the caller's own key, durably.
///
/// A key that does not exist and a key owned by someone else are the same
/// typed NOT_FOUND, so key ids cannot be probed. A persist failure is a
/// 500, not a success — the manager rolls the in-memory flip back, so the
/// reported state always matches what the next boot will load.
pub async fn revoke_api_key_handler(
    State(state): State<AppState>,
    Extension(auth_info): Extension<AuthInfo>,
    Path(key_id): Path<String>,
) -> (StatusCode, Json<RevokeKeyResponse>) {
    match state
        .session_manager
        .auth_manager()
        .revoke_api_key(&auth_info.user_id, &key_id)
        .await
    {
        Ok(()) => {
            info!("API key {} revoked by user {}", key_id, auth_info.user_id);
            (
                StatusCode::OK,
                Json(RevokeKeyResponse {
                    success: true,
                    message: "Key revoked".to_string(),
                    error: None,
                }),
            )
        }
        Err(SessionError::AccessDenied) => (
            StatusCode::NOT_FOUND,
            Json(RevokeKeyResponse {
                success: false,
                message: "No such key".to_string(),
                error: Some("KEY_NOT_FOUND".to_string()),
            }),
        ),
        Err(e) => {
            error!(
                "API-key revocation persist failed for user {} key {}: {:?}",
                auth_info.user_id, key_id, e
            );
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(RevokeKeyResponse {
                    success: false,
                    message: "Revocation could not be persisted — the key is still active"
                        .to_string(),
                    error: Some("REVOCATION_PERSIST_FAILED".to_string()),
                }),
            )
        }
    }
}

