      } catch (e) {
        return fail(e);
      }
    },
  );

  server.tool(
    "get_part",
    "Full report for one part: world placement in mm (center, dimensions, " +
      "anchor datum), topology fingerprint, name.",
    { part_id: z.number().int().describe("part id (list_parts)") },
    async ({ part_id }) => {
      try {
        return ok(await api("GET", `/api/agent/parts/${part_id}`));
      } catch (e) {
        return fail(e);
      }
